func (bb *BatchBuffer) batchUpsertWithRetry(ctx context.Context, records []*shadow.UpsertRecord) (int, []RecordExecutionResult, error) {
	const maxAttempts = 3
	var lastErr error

	for attempt := 1; attempt <= maxAttempts; attempt++ {
		written, results, err := bb.batchUpsert(ctx, records)
		if err == nil {
			return written, results, nil
		}
		lastErr = err

		if !isRetryableDBError(err) {
			break
		}

